__NUXT_JSONP__("/svet/mesto/tanga", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y){return {data:[{place:[{id:n,id_state:o,name:p,population:273332,area:46.16,altitude:35,slug:q,information_chatgpt:a,coordinates:[{latitude:-5.07,longitude:39.1}],biggest:"yes",type_place:d,id_image_cover:a,id_image_hero:a,affiliate:[{name:r,value:s}],alerts:a,zoom:[{google:10,booking:11}],parking:a,information_author:a,importance:e,seo_tags:a}],imagePlace:[],placeState:[{tld:".tz",name:"Tanzanie",area:945087,population:58005461,slug:t,id_continent:g,information_chatgpt:"\u003Cp\u003ETanzanie, oficiálně sjednocená tanzanská republika, je stát východní Afriky, který se rozprostírá přes 947 303 km². S populací přes 58 milionů lidí je Tanzania nejlidnatějším východoafrickým státem a zároveň domovem několika etnických skupin a kultur.\u003C\u002Fp\u003E\n\u003Cp\u003ETanzanie se říká \"domov Big Five\" kvůli tomu, že je domovem největších afrických savců: slonů, buvolů, lvů, leopardů a nosorožců. Kromě toho zde najdeme i mnoho dalších druhů zvířat, jako jsou zebr, žirafy a hyeny. Národní parky jako Serengeti, Ngorongoro Crater a Manyara jsou velmi populární turistické atrakce, kde si můžete vychutnat africkou divočinu a její nezapomenutelné zážitky.\u003C\u002Fp\u003E\n\u003Cp\u003ETanzanie má také dlouhou historii a kulturu, která se projevuje v různých tradicích a obyčejích. Například etnikum Masajové jsou známí svým bohatým folklórem, tanci a oděvy. Stejně tak můžete navštívit mnoho historických památek, jako jsou starobylé kameny v městě Bagamoyo a Staré město v Stone Townu na ostrově Zanzibar.\u003C\u002Fp\u003E\n\u003Cp\u003EPláže Zanzibaru patří k nejkrásnějším na světě a přitahují turisty ze všech koutů světa. Turisté se mohou těšit na křišťálově čisté vody Indického oceánu, bílý písek a kouzelnou atmosféru. Zanzibar je také domovem mnoha koralových útesů a mořských živočichů, což přitahuje potápěče a šnorchlaře.\u003C\u002Fp\u003E\n\u003Cp\u003ETanzanie je známá svou rozmanitou kuchyní, která se skládá z mnoha různých kuchyní etnických skupin. Mezi místní speciality patří urojo (polévka z ovesných vloček), wali na maharage (rýže s fazolemi) a mishkaki (grilované maso na špejli).\u003C\u002Fp\u003E",currency_code:"TZS",currency_name:"Tanzanský šilink",money_prices:[{name:"Taxi (cena za km)",value:1750,date_update:f},{name:"Hlavní jídlo",value:8000,date_update:f},{name:"Chleba",value:2250,date_update:f},{name:"Mléko",value:a,date_update:f},{name:"Voda (500ml)",value:u,date_update:f},{name:"Espresso",value:a,date_update:f},{name:"Zmrzlina (jeden kopeček)",value:u,date_update:f},{name:"Pivo",value:3250,date_update:f},{name:"Krabička cigaret",value:4500,date_update:f},{name:"Bic Mac",value:a,date_update:f},{name:"Coca Cola (500ml)",value:1500,date_update:f}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:h,date_update:c},{name:"Policie",value:h,date_update:c},{name:"Hasiči",value:h,date_update:c},{name:"Zdravotnická záchranná služba",value:h,date_update:c},{name:"Turistická policie",value:"+255 754 562 254",date_update:c},{name:"Horská záchranná služba",value:"+255 27 275 0636",date_update:c},{name:"Pobřežní záchranná služba",value:"+255 22 211 7055",date_update:c}],phone_prefix:"+255",coordinates:[{latitude:"-6.3690",longitude:"34.8888"}],people_religion:[{name:"Muslime",value:"35%",date_update:k},{name:"Křesťané",value:"60%",date_update:k},{name:"Tradiční africká náboženství",value:"5%",date_update:k}],people_nationality:[{name:"Sukuma",value:"16.0%",date_update:b},{name:"Nyamwezi",value:"13.0%",date_update:b},{name:"Chagga",value:"9.0%",date_update:b},{name:"Haya",value:"5.5%",date_update:b},{name:"Nyakyusa",value:"5.0%",date_update:b},{name:"Hehe",value:v,date_update:b},{name:"Makonde",value:v,date_update:b},{name:"Mwera",value:l,date_update:b},{name:"Safwa",value:l,date_update:b},{name:w,value:l,date_update:b},{name:"Kerewe",value:"2.6%",date_update:b},{name:"Zaramo",value:"2.5%",date_update:b},{name:"Maasai",value:i,date_update:b},{name:"Sambaa",value:i,date_update:b},{name:"Iraqw",value:i,date_update:b},{name:"Gorowa",value:i,date_update:b},{name:"Makua",value:"1.7%",date_update:b},{name:"Rangi",value:"1.6%",date_update:b},{name:"Bondei",value:j,date_update:b},{name:"Datooga",value:j,date_update:b},{name:"Manyema",value:j,date_update:b},{name:w,value:j,date_update:b}],visitors_entry:[{name:"Občanský průkaz",value:"Pro vstup do Tanzanie je potřeba mít platný cestovní pas, občanský průkaz není akceptován jako cestovní doklad.",date_update:c},{name:"Cestovní pas",value:"Pro vstup do Tanzanie je nutné mít platný cestovní pas, který je platný minimálně 6 měsíců od data příjezdu do země.",date_update:c},{name:"Vízum",value:"Pro vstup do Tanzanie je potřeba mít vízum, pokud cestujete jako turista. Občané České republiky mohou získat vízum při příjezdu na letišti nebo na hranicích, a to za poplatek. Pokud cestujete do Tanzanie za jiným účelem než turistikou, je třeba si vízum zajistit předem.",date_update:c},{name:"Očkování",value:"Pro vstup do Tanzanie není nutné očkování, pokud však cestujete z některých zemí s vysokým výskytem určitých nemocí, jako je např. žlutá zimnice, může být očkování vyžadováno. Pro občany České republiky se doporučuje očkování proti žluté zimnici, hepatitidě A a B, břišnímu tyfu a zápalu plic.",date_update:c},{name:"Cestovní pojištění",value:"Cestovní pojištění není povinné, ale je vřele doporučováno pro případ zdravotních potíží během pobytu v Tanzanii. Vzhledem k vysokým nákladům na léčbu a evakuaci zpět do České republiky je vhodné mít sjednané pojištění, které pokryje všechny potřebné náklady.",date_update:c},{name:"Bezpečnostní situace",value:"V Tanzanii může být vysoká kriminalita, zejména v městských oblastech. Cestovatelům se proto doporučuje být opatrní a neukazovat příliš své cennosti. V některých částech země může být také vysoké riziko teroristických útoků a únosů. Vzhledem k bezpečnostní situaci je vhodné sledovat aktuální zpravodajství a informace od místních úřadů.",date_update:c},{name:"Další informace",value:"Při cestování do Tanzanie je dobré být obeznámen s místními zvyklostmi a kulturou. Například se zde očekává, že ženy budou nosit zahalené ramena a kozy nebo ovce budou přednostně používány k dopravě zboží. Také se doporučuje dodržovat náboženské zvyklosti a respektovat místní zvyklosti.",date_update:c}],type_place:x,id_image_cover:m,id_image_hero:m,id_city_main:y,affiliate:[{name:r,value:s}],mpz:"TZ",alerts:a,zoom:[{google:g,booking:6}],ids_neighboring_countries:[{id:24},{id:40},{id:115},{id:156},{id:159},{id:192},{id:231},{id:248}],organization:a,apps:a,links:a,information_author:a,seo_tags:a,language_phrases:a,wall_sockets:a,id:o,facts:a}],imageState:[{id:m,name:t,source:"\u002Fworld\u002Fstates\u002F",date_create:"2023-05-03T22:13:53.42428+00:00",type:x,author:"pixabay.com"}],placeContinent:[{id:g,slug:"afrika",name:"Afrika",area:30370000,population:1340000000,population_density:44.12,number_states:54,information_chatgpt:"\u003Cp\u003EAfrika je největší kontinent na Zemi a rozkládá se na ploše přesahující 30 milionů kilometrů čtverečních. Nachází se zde více než 50 zemí a žije zde více než 1,3 miliardy lidí. \u003C\u002Fp\u003E\n\u003Cp\u003EJižní Afrika, Egypt, Maroko a Keňa patří mezi nejoblíbenější turistické cíle v Africe. V Jihoafrické republice se můžete podívat na slavné Krugerův národní park a sledovat zde život zvířat v jejich přirozeném prostředí. Egypt je zase proslulý svými pyramidami, které se nacházejí v Gíze. V Maroku můžete navštívit tradiční trhy, zatímco v Keni se můžete setkat s Masajským kmenem a podívat se na úžasnou přírodu.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika má bohatou historii a kulturu. První lidé, kteří se usadili v Africe, byli loveckým a sběračským národem. Poté se v této oblasti objevily první civilizace, jako je Kúšská říše, Egyptská říše nebo Království Aksum. Afrika byla také kolonizována evropskými mocnostmi a toto období mělo značný dopad na dnešní politickou situaci na kontinentu.\u003C\u002Fp\u003E\n\u003Cp\u003EJe důležité zmínit, že Afrika má velké množství jazyků a kultur. Zahrnuje mnoho různých národů a etnických skupin, a to má vliv na různorodost obyvatelstva a kultury. Nejrozšířenějším jazykem je arabština, která se mluví především v severní Africe a v některých částech západní Afriky. Dalšími důležitými jazyky jsou svahilština, francouzština, portugalština, angličtina a mnoho dalších.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika má také nádhernou přírodu. Nachází se zde nejvyšší hora světa, Kilimandžáro, která se nachází na území Tanzanie a Keňy. Kromě toho se v Africe nachází také největší pouště na světě, Sahara, a největší prales, Kongský prales. Na tomto kontinentě můžete vidět také mnoho zvířat, jako jsou sloni, lvi, gepardi, zebry a mnoho dalších druhů. V Africe se také nachází několik nejvýznamnějších řek světa, jako je Nil, Kongo, Niger a Zambezi.\u003C\u002Fp\u003E\u003Cp\u003EAfrika je bohužel také známá pro své problémy. Mnoho zemí se potýká s chudobou, nedostatkem potravin a vody, nemocemi a válečnými konflikty. Mnoho afrických zemí závisí na zemědělství a rybolovu, což však často není dostatečně výnosné, aby zabezpečilo potřeby obyvatelstva. Kromě toho jsou některé země v Africe trvale postižené extrémními přírodními katastrofami, jako jsou sucha, povodně a bouře.\u003C\u002Fp\u003E\n\u003Cp\u003ENa druhou stranu se v Africe také nachází mnoho lidí, kteří se snaží změnit situaci a zlepšit životy svých spoluobčanů. Vznikají neziskové organizace, které se snaží pomáhat při řešení těchto problémů a zlepšovat kvalitu života v mnoha afrických zemích. Zároveň se v posledních letech objevují nové možnosti pro ekonomický růst a rozvoj, jako jsou technologické start-upy a zahraniční investice.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika je fascinující kontinent, který nabízí mnoho zážitků a zároveň v sobě ukrývá mnoho výzev. Pokud se rozhodnete navštívit Afriku, můžete se těšit na krásnou přírodu, bohatou kulturu a nezapomenutelné zážitky. Je však také důležité být obezřetný a připravený na místní podmínky, protože některé oblasti mohou být nebezpečné kvůli konfliktům nebo zločinnosti.\u003C\u002Fp\u003E",coordinates:[{latitude:1.650801,longitude:17.371642}],type_place:"continent",id_image_cover:g,id_image_hero:g,zoom:[{google:2,booking:3}],information_author:a,seo_tags:a}],placesCities:[{id:2265,id_image_cover:a,importance:e,slug:"arusha",type_place:d,name:"Arusha"},{id:2263,id_image_cover:a,importance:e,slug:"dar-es-salaam",type_place:d,name:"Dar es Salaam"},{id:y,id_image_cover:a,importance:e,slug:"dodoma",type_place:d,name:"Dodoma"},{id:2270,id_image_cover:a,importance:e,slug:"kigoma",type_place:d,name:"Kigoma"},{id:2267,id_image_cover:a,importance:e,slug:"mbeya",type_place:d,name:"Mbeya"},{id:2269,id_image_cover:a,importance:e,slug:"morogoro",type_place:d,name:"Morogoro"},{id:2264,id_image_cover:a,importance:e,slug:"mwanza",type_place:d,name:"Mwanza"},{id:2272,id_image_cover:a,importance:e,slug:"songea",type_place:d,name:"Songea"},{id:n,id_image_cover:a,importance:e,slug:q,type_place:d,name:p},{id:2271,id_image_cover:a,importance:e,slug:"zanzibar",type_place:d,name:"Zanzibar"}],imagesCities:a}],fetch:{"OrganismsoPlaceTeaserSpotsComponent:0":{spots:[],images:a},"OrganismsoSidebarListComponent:0":{events:[],images:a}},mutations:[]}}(null,"04-2012","05-2023","city","biggest","Květen 2023",5,"112","2.0%","1.5%","12-2019","3.0%",372,2268,229,"Tanga","tanga","booking",true,"tanzanie",750,"4.0%","Gogo","state",2266)));